// Generated by scripts/prepare.mjs
export const bundledExamples = {"/examples/01_multi_output.js":"// No DAW or manual MIDI connection needed. Choose this Run file and press Run.\n// Stop releases all three loops. The native sound rack stays enabled for Keyboard.\nawait enableSoundChip(\"ym2612\");\nawait enableSoundChip(\"sega-psg\");\nsetBpm(120);\n\nconst piano = midi.output(\"tetorica-ym2612\", { channel: 1 });\nconst bass = midi.output(\"tetorica-ym2612\", { channel: 2 });\nconst lead = midi.output(\"tetorica-sega-psg\", { channel: 1 });\n\nliveLoop(\"piano\", async () => {\n  piano.play(cycle([\"C4\", \"E4\", \"G4\", \"E4\"]), { duration: 0.4, velocity: 80 });\n  await beat(0.5);\n});\nliveLoop(\"bass\", async () => {\n  bass.play(cycle([\"C3\", \"G2\"]), { duration: 0.8, velocity: 90 });\n  await beat(1);\n});\nliveLoop(\"lead\", async () => {\n  lead.play(cycle([\"C5\", \"E5\", \"G5\", \"E5\"]), { duration: 0.15, velocity: 65 });\n  await beat(0.25);\n});\n// PSG CH10 is fixed white noise. YM2612 currently uses a fixed FM patch on every CH.\n// External ports can instead be selected by their unique name in midi.output().\n","/examples/02_assigned_outputs.js":"// Press Run: internal destinations work without manual MIDI assignments.\n// To use assignments instead, set MIDI_OUTPUT_01 / 02 in MIDI connections,\n// then replace \"tetorica-ym2612\" with MIDI_OUTPUT_01 (without quotes)\n// and \"tetorica-sega-psg\" with MIDI_OUTPUT_02 in the output calls below.\nawait enableSoundChip(\"ym2612\");\nawait enableSoundChip(\"sega-psg\");\nconst piano = midi.output(\"tetorica-ym2612\", { channel: 1 });\nconst bass = midi.output(\"tetorica-ym2612\", { channel: 2 });\nconst lead = midi.output(\"tetorica-sega-psg\", { channel: 1 });\nliveLoop(\"piano\", async () => {\n  piano.play(\"C4\", { duration: 0.4 });\n  await beat(0.5);\n});\nliveLoop(\"bass\", async () => {\n  bass.play(\"C3\", { duration: 0.8 });\n  await beat(1);\n});\nliveLoop(\"lead\", async () => {\n  lead.play(\"G4\", { duration: 0.2 });\n  await beat(0.25);\n});\n","/examples/03_context_jsdoc.js":"// Run this file: the built-in YM2612 plays a repeating phrase. No DAW needed.\n// Try context. and instrument. completion, or change the notes and duration.\nawait enableSoundChip(\"ym2612\");\nconst piano = midi.output(\"tetorica-ym2612\", { channel: 1 });\n\n/**\n * Play a phrase with loop-local timing and cancellation.\n * @param {TetoricaContext} context\n * @param {MidiOutput} instrument\n * @returns {Promise<void>}\n */\nasync function phrase(context, instrument) {\n  for (const note of [\"C4\", \"E4\", \"G4\", \"B4\"]) {\n    await context.playOutput(instrument, note, { duration: 0.5, velocity: 90 });\n  }\n}\n\nliveLoop(\"phrase\", async context => {\n  await phrase(context, piano);\n  await context.beat(1);\n});\n","/examples/04_first_note.js":"// No DAW or MIDI setup needed. Select this file as Run file, then press Run.\n// Plays one C4. Try another note, velocity or duration (in beats).\nawait enableSoundChip(\"ym2612\");\nconst instrument = midi.output(\"tetorica-ym2612\", { channel: 1 });\nawait instrument.play(\"C4\", { duration: 1, velocity: 90 });\n","/examples/05_live_loop.js":"// No DAW needed. Run repeats a melody; Stop releases its notes.\n// Change the notes, duration or gap; use Apply to replace the loop while playing.\nawait enableSoundChip(\"ym2612\");\nconst instrument = midi.output(\"tetorica-ym2612\", { channel: 1 });\nliveLoop(\"melody\", async context => {\n  const note = context.cycle([\"C4\", \"E4\", \"G4\", \"E4\"]);\n  await context.playOutput(instrument, note, { duration: 0.5 });\n  await context.beat(0.25);\n});\n","/examples/06_multi_channel.js":"// No DAW needed. One YM2612 receives two simultaneous parts on CH1 and CH2.\n// Both channels share six FM voices. Edit each channel's patch in the YM2612 tab.\n// Try changing the bass note or the gap. Stop ends both loops.\nawait enableSoundChip(\"ym2612\");\nconst lead = midi.output(\"tetorica-ym2612\", { channel: 1 });\nconst bass = midi.output(\"tetorica-ym2612\", { channel: 2 });\nliveLoop(\"lead\", async context => {\n  await context.playOutput(lead, context.cycle([\"C4\", \"E4\", \"G4\"]), { duration: 0.5 });\n  await context.beat(0.25);\n});\nliveLoop(\"bass\", async context => {\n  await context.playOutput(bass, \"C3\", { duration: 1 });\n  await context.beat(0.5);\n});\n","/examples/07_external_output.js":"// SETUP: open a MIDI receiver and choose an instrument there first.\n// Replace the name below with the exact output port name shown in MIDI connections.\n// Port names are not DAW track names. CH routing depends on the receiving app.\n// Run plays C4 once. Try another channel only if your receiver supports it.\nconst instrument = midi.output(\"REPLACE WITH YOUR MIDI OUTPUT NAME\", { channel: 1 });\nawait instrument.play(\"C4\", { duration: 1, velocity: 90 });\n","/examples/08_output_slots.js":"// SETUP: in MIDI connections assign MIDI_OUTPUT_01 to tetorica-ym2612\n// and MIDI_OUTPUT_02 to tetorica-sega-psg. These assignments are required.\n// Run plays FM C4 and PSG G4 together. Try different channels or destinations.\n// You can assign external MIDI ports instead; prepare their instruments first.\nawait enableSoundChip(\"ym2612\");\nawait enableSoundChip(\"sega-psg\");\nconst fm = midi.output(MIDI_OUTPUT_01, { channel: 1 });\nconst psg = midi.output(MIDI_OUTPUT_02, { channel: 2 });\nawait Promise.all([\n  fm.play(\"C4\", { duration: 1, velocity: 90 }),\n  psg.play(\"G4\", { duration: 1, velocity: 90 }),\n]);\n"};
